package com.example.paymentservicefeb25.services;
import com.example.paymentservicefeb25.models.*; import com.example.paymentservicefeb25.outbox.OutboxEvent; import com.example.paymentservicefeb25.outbox.OutboxEventRepository; import com.example.paymentservicefeb25.paymentgateways.PaymentGateway; import com.example.paymentservicefeb25.repositories.*; import com.fasterxml.jackson.databind.ObjectMapper; import com.stripe.exception.StripeException; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.*;
@Service public class PaymentService { private final PaymentGateway gateway; private final KafkaTemplate<String,String> kafka; private final ObjectMapper mapper; private final PaymentRepository payments; private final ProcessedPaymentEventRepository processed; private final PaymentIdempotencyRepository idempotency; private final OutboxEventRepository outbox; public PaymentService(PaymentGateway gateway,KafkaTemplate<String,String> kafka,ObjectMapper mapper,PaymentRepository payments,ProcessedPaymentEventRepository processed,PaymentIdempotencyRepository idempotency, OutboxEventRepository outbox){this.gateway=gateway;this.kafka=kafka;this.mapper=mapper;this.payments=payments;this.processed=processed;this.idempotency=idempotency; this.outbox=outbox;}
 @Transactional public String initiatePayment(Long orderId, java.math.BigDecimal amount, String idempotencyKey) throws StripeException { if(orderId==null || amount==null || amount.signum()<=0) throw new IllegalArgumentException("orderId and positive amount are required");
   if(idempotencyKey==null||idempotencyKey.isBlank()) throw new IllegalArgumentException("Idempotency-Key is required");
   if(idempotency.claimKey(idempotencyKey, orderId)==0){ var prior=idempotency.findByIdempotencyKey(idempotencyKey).orElseThrow(); if(!prior.getOrderId().equals(orderId)) throw new IllegalArgumentException("Idempotency-Key was used for another order"); if(prior.getPaymentId()==null) throw new IllegalStateException("Payment request is currently being processed"); return "PAYMENT_ALREADY_INITIATED"; } Payment p=payments.findByOrderId(orderId).orElseGet(()->{Payment x=new Payment();x.setOrderId(orderId);x.setCreatedAt(Instant.now());return x;}); if(p.getStatus()==PaymentStatus.SUCCEEDED) throw new IllegalStateException("Payment already completed"); p.setAmount(amount); p.setStatus(PaymentStatus.INITIATED);p.setUpdatedAt(Instant.now());payments.save(p);String link=gateway.initiatePayment(orderId, amount); PaymentIdempotency key=idempotency.findByIdempotencyKey(idempotencyKey).orElseThrow(); key.setPaymentId(p.getId()); idempotency.save(key); saveOutbox("PaymentInitiated",orderId,null,idempotencyKey);return link;}
 @Transactional public void processWebhook(String eventId,String type,Long orderId,String providerId){ if(eventId==null||orderId==null)throw new IllegalArgumentException("eventId/orderId required"); if(processed.existsByEventId(eventId))return; Payment p=payments.findByOrderId(orderId).orElseGet(()->{Payment x=new Payment();x.setOrderId(orderId);x.setCreatedAt(Instant.now());return x;}); p.setProviderPaymentId(providerId);p.setUpdatedAt(Instant.now()); if("PaymentSucceeded".equals(type))p.setStatus(PaymentStatus.SUCCEEDED); else if("PaymentFailed".equals(type))p.setStatus(PaymentStatus.FAILED); else return; payments.save(p);ProcessedPaymentEvent pe=new ProcessedPaymentEvent();pe.setEventId(eventId);pe.setProcessedAt(Instant.now());processed.save(pe);saveOutbox(type,orderId,providerId,eventId);}
 private void saveOutbox(String type,Long orderId,String providerId,String correlation){try{Map<String,Object> e=new LinkedHashMap<>();String eventId=UUID.randomUUID().toString();e.put("eventId",eventId);e.put("eventType",type);e.put("eventVersion",1);e.put("source","PaymentServiceFeb25");e.put("occurredAt",Instant.now().toString());e.put("orderId",orderId);e.put("providerPaymentId",providerId);e.put("correlationId",correlation);OutboxEvent o=new OutboxEvent();o.setEventId(eventId);o.setTopic("payment-events");o.setEventKey(String.valueOf(orderId));o.setPayload(mapper.writeValueAsString(e));outbox.save(o);}catch(Exception ex){throw new IllegalStateException("Unable to create payment outbox event",ex);}}
}
